(function(){"use strict";document.querySelectorAll("form[data-confirm]").forEach(function(t){t.addEventListener("submit",function(e){window.confirm(t.getAttribute("data-confirm"))||e.preventDefault()})}),document.querySelectorAll(".bar span[data-w]").forEach(function(t){t.style.setProperty("--w",Math.max(0,Math.min(100,parseFloat(t.getAttribute("data-w"))||0))+"%")}),document.querySelectorAll("select[data-autosubmit]").forEach(function(t){t.addEventListener("change",function(){t.form.submit()})})})();
